/**
 * Admin Password Reset API
 *
 * POST /api/admin/users/[userId]/reset-password
 *
 * Generates a new temporary password, hashes it, purges sessions,
 * and returns the plaintext password once for admin to share.
 */

import { NextResponse } from 'next/server';
import { hash } from 'bcryptjs';
import { db } from '@/lib/db';
import {
  requireAdmin,
  createAuditLog,
  getClientIp,
} from '@/lib/rbac';
import { AUDIT_ACTIONS } from '@/lib/admin-types';

export const dynamic = "force-dynamic";

type RouteContext = {
  params: Promise<{ userId: string }>;
};

function generateSecurePassword(): string {
  const chars = 'ABCDEFGHJKLMNPQRSTUVWXYZabcdefghjkmnpqrstuvwxyz23456789!@#$%';
  let password = '';
  for (let i = 0; i < 16; i++) {
    password += chars.charAt(Math.floor(Math.random() * chars.length));
  }
  return password;
}

export async function POST(request: Request, context: RouteContext) {
  try {
    const session = await requireAdmin();
    const { userId } = await context.params;

    // Optionally accept a specific password from admin
    let body: { newPassword?: string } = {};
    try {
      body = await request.json();
    } catch {
      // Empty body is fine — we'll auto-generate
    }

    // Check target user exists
    const targetUser = await db.user.findUnique({
      where: { id: userId },
      select: { id: true, name: true, email: true },
    });
    if (!targetUser) {
      return NextResponse.json({ message: 'User not found.' }, { status: 404 });
    }

    // Generate or use provided password
    const rawPassword = body.newPassword ?? generateSecurePassword();

    if (rawPassword.length < 6) {
      return NextResponse.json(
        { message: 'Password must be at least 6 characters.' },
        { status: 400 }
      );
    }

    const hashedPassword = await hash(rawPassword, 10);

    // Update password and purge all sessions
    await db.$transaction([
      db.user.update({
        where: { id: userId },
        data: { password: hashedPassword },
      }),
      db.session.deleteMany({ where: { userId } }),
    ]);

    // Audit log
    await createAuditLog({
      adminId: session.user.id,
      targetId: userId,
      action: AUDIT_ACTIONS.PASSWORD_RESET,
      ipAddress: getClientIp(request),
      metadata: {
        targetEmail: targetUser.email,
        targetName: targetUser.name,
        method: body.newPassword ? 'admin-specified' : 'auto-generated',
      },
    });

    return NextResponse.json({
      message: 'Password reset successfully. Share this temporary password securely.',
      temporaryPassword: rawPassword,
      note: 'This password is shown only once. The user should change it upon next login.',
    });
  } catch (err) {
    const error = err as { status?: number; message?: string };
    console.error('ADMIN_PASSWORD_RESET_ERROR', err);
    return NextResponse.json(
      { message: error.message ?? 'Internal server error.' },
      { status: error.status ?? 500 }
    );
  }
}

/**
 * Admin Role Change API — Re-authenticated role escalation
 *
 * PATCH /api/admin/users/[userId]/role
 *
 * Requires admin re-authentication (password) to prevent unauthorized role escalation.
 */

import { NextResponse } from 'next/server';
import { db } from '@/lib/db';
import {
  requireAdmin,
  requireReAuth,
  createAuditLog,
  getClientIp,
} from '@/lib/rbac';
import {
  normalizeRole,
  DEFAULT_ROLE_PERMISSIONS,
  AUDIT_ACTIONS,
  type UserRole,
} from '@/lib/admin-types';

export const dynamic = "force-dynamic";

type RouteContext = {
  params: Promise<{ userId: string }>;
};

const VALID_ROLES: UserRole[] = ['ADMIN', 'INSTRUCTOR', 'STUDENT'];

export async function PATCH(request: Request, context: RouteContext) {
  try {
    const session = await requireAdmin();
    const { userId } = await context.params;
    const body = await request.json();

    const { newRole, adminPassword } = body as {
      newRole?: string;
      adminPassword?: string;
    };

    if (!newRole || !adminPassword) {
      return NextResponse.json(
        { message: 'newRole and adminPassword are required.' },
        { status: 400 }
      );
    }

    const normalizedNewRole = normalizeRole(newRole);
    if (!VALID_ROLES.includes(normalizedNewRole)) {
      return NextResponse.json(
        { message: `Invalid role: ${newRole}. Must be ADMIN, INSTRUCTOR, or STUDENT.` },
        { status: 400 }
      );
    }

    // Re-authenticate the admin
    await requireReAuth(session.user.id, adminPassword);

    // Prevent self-role-change
    if (userId === session.user.id) {
      return NextResponse.json(
        { message: 'Cannot change your own role.' },
        { status: 400 }
      );
    }

    // Check target user exists
    const targetUser = await db.user.findUnique({
      where: { id: userId },
      select: { id: true, role: true, name: true, email: true },
    });
    if (!targetUser) {
      return NextResponse.json({ message: 'User not found.' }, { status: 404 });
    }

    const oldRole = normalizeRole(targetUser.role);
    if (oldRole === normalizedNewRole) {
      return NextResponse.json(
        { message: `User already has role ${normalizedNewRole}.` },
        { status: 400 }
      );
    }

    // Map to DB role string
    const dbRole = normalizedNewRole === 'INSTRUCTOR' ? 'PROFESSOR' : normalizedNewRole;
    const newPermissions = DEFAULT_ROLE_PERMISSIONS[normalizedNewRole];

    // Update role, permissions, and purge sessions (force re-login)
    await db.$transaction([
      db.user.update({
        where: { id: userId },
        data: {
          role: dbRole,
          permissions: JSON.stringify(newPermissions),
        },
      }),
      db.session.deleteMany({ where: { userId } }),
    ]);

    // Audit log
    await createAuditLog({
      adminId: session.user.id,
      targetId: userId,
      action: `${AUDIT_ACTIONS.ROLE_CHANGE}_TO_${normalizedNewRole}`,
      ipAddress: getClientIp(request),
      metadata: {
        previousRole: oldRole,
        newRole: normalizedNewRole,
        targetEmail: targetUser.email,
      },
    });

    return NextResponse.json({
      message: `Role changed from ${oldRole} to ${normalizedNewRole}. User sessions have been purged.`,
    });
  } catch (err) {
    const error = err as { status?: number; message?: string };
    console.error('ADMIN_ROLE_CHANGE_ERROR', err);
    return NextResponse.json(
      { message: error.message ?? 'Internal server error.' },
      { status: error.status ?? 500 }
    );
  }
}

/**
 * Admin Single User API — Get, Update, Delete
 *
 * GET    /api/admin/users/[userId] — Fetch single user profile
 * PATCH  /api/admin/users/[userId] — Update user fields
 * DELETE /api/admin/users/[userId] — Deactivate user
 */

import { NextResponse } from 'next/server';
import { db } from '@/lib/db';
import {
  requireAdmin,
  createAuditLog,
  getClientIp,
  parsePermissions,
} from '@/lib/rbac';
import { normalizeRole, AUDIT_ACTIONS } from '@/lib/admin-types';

export const dynamic = "force-dynamic";

type RouteContext = {
  params: Promise<{ userId: string }>;
};

export async function GET(request: Request, context: RouteContext) {
  try {
    await requireAdmin();
    const { userId } = await context.params;

    const user = await db.user.findUnique({
      where: { id: userId },
      select: {
        id: true,
        name: true,
        email: true,
        uniqueId: true,
        role: true,
        isActive: true,
        permissions: true,
        createdAt: true,
        institute: { select: { code: true, name: true } },
      },
    });

    if (!user) {
      return NextResponse.json({ message: 'User not found.' }, { status: 404 });
    }

    return NextResponse.json({
      user: {
        id: user.id,
        name: user.name,
        email: user.email,
        uniqueId: user.uniqueId,
        role: normalizeRole(user.role),
        isActive: user.isActive,
        permissions: parsePermissions(user.permissions),
        createdAt: user.createdAt.toISOString(),
        instituteCode: user.institute.code,
        instituteName: user.institute.name,
      },
    });
  } catch (err) {
    const error = err as { status?: number; message?: string };
    return NextResponse.json(
      { message: error.message ?? 'Internal server error.' },
      { status: error.status ?? 500 }
    );
  }
}

export async function PATCH(request: Request, context: RouteContext) {
  try {
    const session = await requireAdmin();
    const { userId } = await context.params;
    const body = await request.json();

    const { name, email, uniqueId, instituteCode } = body as {
      name?: string;
      email?: string;
      uniqueId?: string;
      instituteCode?: string;
    };

    // Check user exists
    const existingUser = await db.user.findUnique({
      where: { id: userId },
      select: { id: true, name: true, email: true, uniqueId: true },
    });
    if (!existingUser) {
      return NextResponse.json({ message: 'User not found.' }, { status: 404 });
    }

    // If email is changing, check for duplicates
    if (email && email.toLowerCase() !== existingUser.email) {
      const duplicate = await db.user.findUnique({
        where: { email: email.toLowerCase() },
      });
      if (duplicate) {
        return NextResponse.json(
          { message: 'Email is already in use by another account.' },
          { status: 409 }
        );
      }
    }

    const updateData: Record<string, unknown> = {};
    if (name !== undefined) updateData.name = name;
    if (email !== undefined) updateData.email = email.toLowerCase();
    if (uniqueId !== undefined) updateData.uniqueId = uniqueId;

    if (instituteCode) {
      const inst = await db.institute.findUnique({
        where: { code: instituteCode.toLowerCase() },
      });
      if (inst) {
        updateData.instituteId = inst.id;
      }
    }

    const updated = await db.user.update({
      where: { id: userId },
      data: updateData,
      select: {
        id: true,
        name: true,
        email: true,
        uniqueId: true,
        role: true,
        isActive: true,
        permissions: true,
        createdAt: true,
        institute: { select: { code: true } },
      },
    });

    // Audit log
    await createAuditLog({
      adminId: session.user.id,
      targetId: userId,
      action: AUDIT_ACTIONS.ACCOUNT_UPDATED,
      ipAddress: getClientIp(request),
      metadata: { changes: updateData },
    });

    return NextResponse.json({
      message: 'User updated successfully.',
      user: {
        ...updated,
        role: normalizeRole(updated.role),
        permissions: parsePermissions(updated.permissions),
        createdAt: updated.createdAt.toISOString(),
        instituteCode: updated.institute.code,
      },
    });
  } catch (err) {
    const error = err as { status?: number; message?: string };
    console.error('ADMIN_UPDATE_USER_ERROR', err);
    return NextResponse.json(
      { message: error.message ?? 'Internal server error.' },
      { status: error.status ?? 500 }
    );
  }
}

export async function DELETE(request: Request, context: RouteContext) {
  try {
    const session = await requireAdmin();
    const { userId } = await context.params;

    const user = await db.user.findUnique({
      where: { id: userId },
      select: { id: true, name: true, email: true },
    });
    if (!user) {
      return NextResponse.json({ message: 'User not found.' }, { status: 404 });
    }

    // Prevent self-deletion
    if (userId === session.user.id) {
      return NextResponse.json(
        { message: 'Cannot delete your own account.' },
        { status: 400 }
      );
    }

    // Soft-delete: deactivate and purge sessions
    await db.$transaction([
      db.user.update({
        where: { id: userId },
        data: { isActive: false },
      }),
      db.session.deleteMany({ where: { userId } }),
    ]);

    // Audit log
    await createAuditLog({
      adminId: session.user.id,
      targetId: userId,
      action: AUDIT_ACTIONS.ACCOUNT_DELETED,
      ipAddress: getClientIp(request),
      metadata: { email: user.email, name: user.name },
    });

    return NextResponse.json({ message: 'User deactivated successfully.' });
  } catch (err) {
    const error = err as { status?: number; message?: string };
    console.error('ADMIN_DELETE_USER_ERROR', err);
    return NextResponse.json(
      { message: error.message ?? 'Internal server error.' },
      { status: error.status ?? 500 }
    );
  }
}

/**
 * Admin Account Status API — Activate / Suspend
 *
 * PATCH /api/admin/users/[userId]/status
 *
 * Toggling to suspended instantly purges all active sessions.
 */

import { NextResponse } from 'next/server';
import { db } from '@/lib/db';
import {
  requireAdmin,
  createAuditLog,
  getClientIp,
} from '@/lib/rbac';
import { AUDIT_ACTIONS } from '@/lib/admin-types';

export const dynamic = "force-dynamic";

type RouteContext = {
  params: Promise<{ userId: string }>;
};

export async function PATCH(request: Request, context: RouteContext) {
  try {
    const session = await requireAdmin();
    const { userId } = await context.params;
    const body = await request.json();

    const { isActive } = body as { isActive?: boolean };

    if (typeof isActive !== 'boolean') {
      return NextResponse.json(
        { message: 'isActive (boolean) is required.' },
        { status: 400 }
      );
    }

    // Prevent self-suspension
    if (userId === session.user.id && !isActive) {
      return NextResponse.json(
        { message: 'Cannot suspend your own account.' },
        { status: 400 }
      );
    }

    // Check target user exists
    const targetUser = await db.user.findUnique({
      where: { id: userId },
      select: { id: true, isActive: true, name: true, email: true },
    });
    if (!targetUser) {
      return NextResponse.json({ message: 'User not found.' }, { status: 404 });
    }

    if (targetUser.isActive === isActive) {
      return NextResponse.json(
        { message: `User is already ${isActive ? 'active' : 'suspended'}.` },
        { status: 400 }
      );
    }

    if (!isActive) {
      // SUSPENSION: deactivate + purge ALL sessions immediately
      await db.$transaction([
        db.user.update({
          where: { id: userId },
          data: { isActive: false },
        }),
        db.session.deleteMany({ where: { userId } }),
      ]);

      await createAuditLog({
        adminId: session.user.id,
        targetId: userId,
        action: AUDIT_ACTIONS.ACCOUNT_SUSPENSION,
        ipAddress: getClientIp(request),
        metadata: { email: targetUser.email, name: targetUser.name },
      });

      return NextResponse.json({
        message: 'Account suspended. All active sessions have been terminated.',
      });
    } else {
      // REACTIVATION
      await db.user.update({
        where: { id: userId },
        data: { isActive: true },
      });

      await createAuditLog({
        adminId: session.user.id,
        targetId: userId,
        action: AUDIT_ACTIONS.ACCOUNT_REACTIVATION,
        ipAddress: getClientIp(request),
        metadata: { email: targetUser.email, name: targetUser.name },
      });

      return NextResponse.json({
        message: 'Account reactivated successfully.',
      });
    }
  } catch (err) {
    const error = err as { status?: number; message?: string };
    console.error('ADMIN_STATUS_CHANGE_ERROR', err);
    return NextResponse.json(
      { message: error.message ?? 'Internal server error.' },
      { status: error.status ?? 500 }
    );
  }
}

