import { NextResponse } from "next/server";
import { hash } from "bcryptjs";
import { db } from "@/lib/db";
import { registerSchema } from "@/lib/auth-schema";
import {
  getClientIp,
  checkRateLimit,
  RATE_LIMIT_CONFIG,
  createRateLimitResponse,
} from "@/lib/rate-limit";
import { getCorsHeaders, handleCorsPreflight } from "@/lib/cors";

export const dynamic = "force-dynamic";

export async function OPTIONS(request: Request) {
  return handleCorsPreflight(request) ?? new NextResponse(null, { status: 204 });
}

export async function POST(request: Request) {
  const corsHeaders = getCorsHeaders(request);

  // 1. Rate limiting check (IP-based)
  const clientIp = getClientIp(request);
  const rateLimitResult = await checkRateLimit(`rl:reg:${clientIp}`, RATE_LIMIT_CONFIG.registerIp);
  if (!rateLimitResult.allowed) {
    const rateLimitResponse = createRateLimitResponse(rateLimitResult);
    for (const [k, v] of Object.entries(corsHeaders)) {
      rateLimitResponse.headers.set(k, v);
    }
    return rateLimitResponse;
  }

  try {
    const body = await request.json();

    // 2. Explicit server-side check: Public registration can NEVER create ADMIN accounts
    if (body?.role?.toUpperCase() === "ADMIN") {
      return NextResponse.json(
        {
          message: "Unauthorized role selection: Administrator accounts cannot be self-registered.",
        },
        { status: 403, headers: corsHeaders }
      );
    }

    // 3. Schema validation
    const parsed = registerSchema.safeParse(body);
    if (!parsed.success) {
      return NextResponse.json(
        {
          message: "Validation failed.",
          errors: parsed.error.flatten().fieldErrors,
        },
        { status: 400, headers: corsHeaders }
      );
    }

    const { name, email, studentNumber, uniqueId, role, password, instituteCode } = parsed.data;

    // 4. Duplicate email verification
    const existingUser = await db.user.findUnique({
      where: { email: email.toLowerCase() },
    });

    if (existingUser) {
      return NextResponse.json(
        { message: "Email is already registered." },
        { status: 409, headers: corsHeaders }
      );
    }

    // 5. Dynamic Institute validation (Strict: NO auto-creation)
    const institute = await db.institute.findUnique({
      where: { code: instituteCode.toLowerCase() },
    });

    if (!institute) {
      return NextResponse.json(
        {
          message: `Invalid institute code '${instituteCode}'. Registration must be with an existing registered institute.`,
        },
        { status: 400, headers: corsHeaders }
      );
    }

    // 6. Secure Password Hashing (12 rounds)
    const hashedPassword = await hash(password, 12);
    // Explicitly restrict to allowed public roles: STUDENT or INSTRUCTOR (mapped to PROFESSOR)
    const userRole = role === "INSTRUCTOR" ? "PROFESSOR" : "STUDENT";

    const user = await db.user.create({
      data: {
        name,
        email: email.toLowerCase(),
        studentNumber: userRole === "STUDENT" ? studentNumber || null : null,
        uniqueId: uniqueId || "",
        password: hashedPassword,
        role: userRole,
        instituteId: institute.id,
      },
      select: {
        id: true,
        name: true,
        email: true,
        role: true,
        institute: {
          select: {
            code: true,
            name: true,
          },
        },
      },
    });

    return NextResponse.json(
      {
        message: "Account created successfully.",
        user,
      },
      { status: 201, headers: corsHeaders }
    );
  } catch (error) {
    console.error("REGISTER_ERROR", error);

    return NextResponse.json(
      { message: "Something went wrong during registration." },
      { status: 500, headers: corsHeaders }
    );
  }
}

apps/web/src/app/api/auth/reset-password.content:
import { NextResponse } from "next/server";
import { db } from "@/lib/db";
import { hash, compare } from "bcryptjs";

export const dynamic = "force-dynamic";

export async function POST(request: Request) {
  try {
    const { email, otp, newPassword } = await request.json();

    if (!email || !otp || !newPassword) {
      return NextResponse.json({ message: "Missing required fields." }, { status: 400 });
    }

    if (newPassword.length < 6) {
      return NextResponse.json({ message: "Password must be at least 6 characters long." }, { status: 400 });
    }

    const cleanOtp = String(otp).trim().replace(/\s+/g, "");

    if (!cleanOtp) {
      return NextResponse.json({ message: "OTP code is required." }, { status: 400 });
    }

    const user = await db.user.findUnique({
      where: { email: email.toLowerCase().trim() },
    });

    if (!user) {
      return NextResponse.json({ message: "Invalid OTP or email." }, { status: 400 });
    }

    if (user.isActive === false) {
      return NextResponse.json(
        { message: "This account has been deactivated. Please contact an administrator." },
        { status: 403 }
      );
    }

    // Find the latest active OTP for this user
    const latestOtpRecord = await db.passwordResetOtp.findFirst({
      where: {
        userId: user.id,
        isUsed: false,
      },
      orderBy: { createdAt: "desc" },
    });

    if (!latestOtpRecord) {
      return NextResponse.json({ message: "Invalid or expired OTP." }, { status: 400 });
    }

    if (latestOtpRecord.expiresAt < new Date()) {
      return NextResponse.json({ message: "OTP has expired. Please request a new one." }, { status: 400 });
    }

    const isValidOtp = await compare(cleanOtp, latestOtpRecord.otpCodeHash);

    if (!isValidOtp) {
      return NextResponse.json({ message: "Invalid OTP." }, { status: 400 });
    }

    // OTP is valid and not expired. Update password and mark OTP as used.
    const hashedPassword = await hash(newPassword, 10);

    // Using a transaction to ensure both operations succeed together
    await db.$transaction([
      db.user.update({
        where: { id: user.id },
        data: { password: hashedPassword },
      }),
      db.passwordResetOtp.update({
        where: { id: latestOtpRecord.id },
        data: { isUsed: true },
      }),
    ]);

    // Optional: Also invalidate all active sessions for this user so they have to log in again
    await db.session.deleteMany({
      where: { userId: user.id }
    });

    return NextResponse.json({ message: "Password has been successfully reset." }, { status: 200 });
  } catch (error) {
    console.error("RESET_PASSWORD_ERROR", error);
    return NextResponse.json(
      { message: "Something went wrong. Please try again." },
      { status: 500 }
    );
  }
}

