/**
 * GET /api/codelab/progress
 *
 * Computes a student's CodeLab progression per language track.
 * Reads `ActivitySubmission.stateCheck` to determine scores and highest passed levels (score >= 60).
 */

import { NextResponse } from "next/server";
import { getSession } from "@/lib/auth-session";
import { checkActivityEligibility } from "@/lib/activity-eligibility";
import { db } from "@/lib/db";
import { ProblemLanguage } from "@/features/interactive-activities/codelab/problems/types";

export const dynamic = "force-dynamic";

export async function GET(request: Request) {
  try {
    const session = await getSession();
    if (!session) {
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
    }

    const eligibility = await checkActivityEligibility();
    if (!eligibility || !eligibility.eligible) {
      return NextResponse.json({ error: "Forbidden: Not eligible for activities" }, { status: 403 });
    }

    const { searchParams } = new URL(request.url);
    const targetLanguage = searchParams.get("language") as ProblemLanguage | null;

    // Fetch student's CodeLab submissions
    const submissions = await db.activitySubmission.findMany({
      where: {
        studentId: session.user.id,
        activityType: "codelab",
      },
      select: {
        score: true,
        passed: true,
        stateCheck: true,
        templateId: true,
      },
    });

    const trackScores: Record<string, Record<number, number>> = {
      python: {},
      cpp: {},
      csharp: {},
      java: {},
      javascript: {},
      sql: {},
      html: {},
      css: {},
    };

    for (const sub of submissions) {
      if (!sub.stateCheck) continue;

      try {
        const state = JSON.parse(sub.stateCheck) as Record<string, unknown>;
        let lang = state.language as string | undefined;
        let level = Number(state.level);

        // Fallback: deduce from templateId pattern "{lang}-level-{N}"
        if (!lang && sub.templateId) {
          const match = sub.templateId.match(/^([a-z0-9]+)-level-(\d+)$/i);
          if (match) {
            lang = match[1].toLowerCase();
            level = parseInt(match[2], 10);
          }
        }

        if (lang && trackScores[lang] !== undefined && !isNaN(level) && level >= 1 && level <= 30) {
          const existingScore = trackScores[lang][level] ?? 0;
          trackScores[lang][level] = Math.max(existingScore, sub.score);
        }
      } catch {
        // Skip unparseable stateCheck
      }
    }

    // Helper to calculate highest passed level
    function getHighestPassed(scores: Record<number, number>): number {
      return Object.entries(scores)
        .filter(([, score]) => score >= 60)
        .map(([lvl]) => parseInt(lvl, 10))
        .reduce((max, lvl) => Math.max(max, lvl), 0);
    }

    if (targetLanguage && trackScores[targetLanguage]) {
      const scores = trackScores[targetLanguage];
      const highestPassedLevel = getHighestPassed(scores);
      return NextResponse.json({
        language: targetLanguage,
        highestPassedLevel,
        scores,
      });
    }

    // Return summary for all tracks
    const allProgress: Record<string, { highestPassedLevel: number; scores: Record<number, number> }> = {};
    for (const [lang, scores] of Object.entries(trackScores)) {
      allProgress[lang] = {
        highestPassedLevel: getHighestPassed(scores),
        scores,
      };
    }

    return NextResponse.json(allProgress);
  } catch (err: unknown) {
    console.error("CODELAB_PROGRESS_ERROR", err);
    return NextResponse.json({ error: "Internal Server Error" }, { status: 500 });
  }
}

apps/web/src/app/api/codelab/run-tests/r.content:
/**
 * POST /api/codelab/run-tests
 *
 * Server-side test execution for CodeLab problems.
 * Runs student code against ALL test cases (public + hidden) on the server.
 * Returns full details for public test cases but only pass/fail for hidden ones.
 *
 * Security:
 *   - Requires valid session (401)
 *   - Requires ICS eligibility (403)
 *   - Hidden test cases never leave the server
 *   - All execution runs in Judge0 sandbox
 */

import { NextResponse } from "next/server";
import { checkActivityEligibility } from "@/lib/activity-eligibility";
import { db } from "@/lib/db";
import { substituteTemplate, evaluateVariables, CodeLabVariable } from "@/features/interactive-activities/codelab/utils/problem-engine";

import { executeJudge0Submission } from "@/features/interactive-activities/codelab/utils/judge0-config";
import { wrapStudentCode, getWrapperLanguageFromId } from "@/features/interactive-activities/codelab/utils/code-wrappers";
import { grantExp } from "@/lib/gamification/grant-exp";
import { EXP_VALUES } from "@/lib/gamification/exp-engine";
import { awardBadgeIfEarned } from "@/lib/gamification/badge-checker";

export const dynamic = "force-dynamic";

const MAX_SOURCE_CODE_BYTES = 64 * 1024;

interface RawTestCase {
  input: string;
  expectedOutput: string;
}

interface TestRunResult {
  index: number;
  passed: boolean;
  isHidden: boolean;
  /** Only present for public test cases */
  input?: string;
  /** Only present for public test cases */
  expectedOutput?: string;
  /** Only present for public test cases */
  actualOutput?: string | null;
  /** Error message, if any */
  error?: string;
  /** Execution time in seconds */
  time?: string;
}

async function executeOnJudge0(
  sourceCode: string,
  languageId: number,
  stdin: string
) {
  return executeJudge0Submission(sourceCode, languageId, stdin);
}

export async function POST(request: Request) {
  try {
    // 1. Auth + eligibility
    const eligibility = await checkActivityEligibility();
    if (!eligibility) {
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
    }
    if (!eligibility.eligible) {
      return NextResponse.json({ error: "Forbidden: Not eligible for activities" }, { status: 403 });
    }

    // 2. Parse request
    const body = (await request.json()) as {
      templateId: string;
      variantSeed: string;
      sourceCode: string;
      languageId: number;
    };

    const { templateId, variantSeed, sourceCode, languageId } = body;

    if (!templateId || !sourceCode || !languageId || !variantSeed) {
      return NextResponse.json(
        { error: "Missing required fields: templateId, variantSeed, sourceCode, languageId" },
        { status: 400 }
      );
    }

    // 3. Size check
    const sourceBytes = new TextEncoder().encode(sourceCode).length;
    if (sourceBytes > MAX_SOURCE_CODE_BYTES) {
      return NextResponse.json(
        { error: `Source code exceeds maximum size of ${MAX_SOURCE_CODE_BYTES / 1024} KB` },
        { status: 413 }
      );
    }

    // 4. Fetch template
    const template = await db.activityTemplate.findUnique({
      where: { id: templateId },
      select: { title: true, variables: true, hiddenTestCases: true, activityType: true },
    });

    if (!template || template.activityType !== "codelab") {
      return NextResponse.json({ error: "Template not found or not a CodeLab" }, { status: 404 });
    }

    // 5. Parse template data
    const variablesObj = JSON.parse((template.variables as string) || "{}");
    const hiddenTestCasesRaw: RawTestCase[] = JSON.parse(
      (template.hiddenTestCases as string) || "[]"
    );
    const publicTestCasesRaw: RawTestCase[] = variablesObj.publicTestCases || [];
    const variablesConfig: CodeLabVariable[] = variablesObj.variablesConfig || [];

    // Evaluate variables deterministic based on seed
    const evaluatedVars = evaluateVariables(variantSeed, variablesConfig);

    // 6. Build full test case list
    const allTestCases: { tc: RawTestCase; isHidden: boolean }[] = [
      ...publicTestCasesRaw.map((tc) => ({ tc, isHidden: false })),
      ...hiddenTestCasesRaw.map((tc) => ({ tc, isHidden: true })),
    ];

    // 7. Execute all test cases
    const results: TestRunResult[] = [];
    let passCount = 0;
    const wrapperLang = getWrapperLanguageFromId(languageId);
    const funcSig = variablesObj.functionSignature || null;

    for (let i = 0; i < allTestCases.length; i++) {
      const { tc, isHidden } = allTestCases[i];
      const substitutedInput = substituteTemplate(tc.input, evaluatedVars);
      const substitutedExpected = substituteTemplate(tc.expectedOutput, evaluatedVars);

      try {
        const executableCode = wrapStudentCode(wrapperLang, sourceCode, funcSig, substitutedInput);
        const judgeResult = await executeOnJudge0(executableCode, languageId, substitutedInput);
        const actualOut = (judgeResult.stdout || "").trim();
        const expectedOut = substitutedExpected.trim();
        const passed = judgeResult.status.id === 3 && actualOut === expectedOut;

        if (passed) passCount++;

        const result: TestRunResult = {
          index: i,
          passed,
          isHidden,
          time: judgeResult.time,
        };

        // Only expose details for public test cases
        if (!isHidden) {
          result.input = substitutedInput;
          result.expectedOutput = substitutedExpected;
          result.actualOutput = actualOut;
          result.error =
            judgeResult.stderr ||
            judgeResult.compile_output ||
            (judgeResult.status.id !== 3 ? judgeResult.status.description : undefined) ||
            undefined;
        }

        results.push(result);
      } catch (err: unknown) {
        const errorMessage = err instanceof Error ? err.message : "Execution failed";
        const result: TestRunResult = {
          index: i,
          passed: false,
          isHidden,
        };
        if (!isHidden) {
          result.input = substitutedInput;
          result.expectedOutput = substitutedExpected;
          result.actualOutput = null;
          result.error = errorMessage;
        }
        results.push(result);
      }
    }

    const totalCount = allTestCases.length;
    const score = totalCount > 0 ? Math.round((passCount / totalCount) * 100) : 0;

    let grantedExp = 0;
    let leveledUp = false;
    let newLevel = 1;

    if (score >= 60) {
      try {
        const studentId = eligibility.session.user.id;
        if (score === 100) {
          const expRes = await grantExp({
            userId: studentId,
            amount: EXP_VALUES.codelab_level_perfect,
            reason: `CodeLab: ${template.title || templateId} — Perfect Score (100%)`,
            source: "codelab",
            idempotencyKey: `codelab_perfect_${templateId}`,
          });
          grantedExp = expRes.grantedAmount;
          leveledUp = expRes.leveledUp;
          newLevel = expRes.newLevel;

          await awardBadgeIfEarned(studentId, "codelab-first");
          await awardBadgeIfEarned(studentId, "codelab-perfect-level");
          await awardBadgeIfEarned(studentId, "perfect-score");
        } else {
          const expRes = await grantExp({
            userId: studentId,
            amount: EXP_VALUES.codelab_level_complete,
            reason: `CodeLab: ${template.title || templateId} — Passed`,
            source: "codelab",
            idempotencyKey: `codelab_pass_${templateId}`,
          });
          grantedExp = expRes.grantedAmount;
          leveledUp = expRes.leveledUp;
          newLevel = expRes.newLevel;

          await awardBadgeIfEarned(studentId, "codelab-first");
        }
      } catch (gamiErr) {
        console.error("GAMIFICATION_RUN_TESTS_ERROR", gamiErr);
      }
    }

    return NextResponse.json({
      results,
      passCount,
      totalCount,
      score,
      allPassed: passCount === totalCount,
      grantedExp,
      leveledUp,
      newLevel,
    });
  } catch (error: unknown) {
    console.error("CODELAB_RUN_TESTS_ERROR", error);
    return NextResponse.json({ error: "Internal Server Error" }, { status: 500 });
  }
}

apps/web/src/app/api/codelab/run/route.t.content:
/**
 * POST /api/codelab/run
 *
 * Simple "run my code" endpoint — forwards student code to Judge0 for
 * freeform execution with optional stdin. No test case evaluation.
 *
 * Security:
 *   - Requires valid session (401)
 *   - Requires ICS eligibility (403)
 *   - All execution runs in Judge0 sandbox
 *   - 64 KB source code limit
 */

import { NextResponse } from "next/server";
import { checkActivityEligibility } from "@/lib/activity-eligibility";
import { executeJudge0Submission } from "@/features/interactive-activities/codelab/utils/judge0-config";
import { wrapStudentCode, getWrapperLanguageFromId } from "@/features/interactive-activities/codelab/utils/code-wrappers";

export const dynamic = "force-dynamic";

const MAX_SOURCE_CODE_BYTES = 64 * 1024;

export async function POST(request: Request) {
  try {
    // 1. Auth + eligibility
    const eligibility = await checkActivityEligibility();
    if (!eligibility) {
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
    }
    if (!eligibility.eligible) {
      return NextResponse.json({ error: "Forbidden: Not eligible for activities" }, { status: 403 });
    }

    // 2. Parse request
    const body = (await request.json()) as {
      sourceCode: string;
      languageId: number;
      stdin?: string;
    };

    const { sourceCode, languageId, stdin } = body;

    if (!sourceCode || !languageId) {
      return NextResponse.json(
        { error: "Missing required fields: sourceCode and languageId" },
        { status: 400 }
      );
    }

    // 3. Size check
    const sourceBytes = new TextEncoder().encode(sourceCode).length;
    if (sourceBytes > MAX_SOURCE_CODE_BYTES) {
      return NextResponse.json(
        { error: `Source code exceeds maximum size of ${MAX_SOURCE_CODE_BYTES / 1024} KB` },
        { status: 413 }
      );
    }

    // 4. Wrap student function with standard I/O harness if needed
    const wrapperLang = getWrapperLanguageFromId(languageId);
    const executableCode = wrapStudentCode(wrapperLang, sourceCode, null, stdin || "");

    // 5. Forward to resilient Judge0 execution engine
    const result = await executeJudge0Submission(executableCode, languageId, stdin || "");
    return NextResponse.json(result);
  } catch (error: unknown) {
    console.error("CODELAB_RUN_ERROR", error);
    return NextResponse.json({ error: "Internal Server Error" }, { status: 500 });
  }
}

