import { NextResponse } from "next/server";
import { db } from "@/lib/db";
import { checkKxEligibility } from "@/lib/kx-eligibility";

export const dynamic = "force-dynamic";

export async function GET(request: Request) {
  const eligibility = await checkKxEligibility(request);
  if (!eligibility) {
    return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
  }

  if (!eligibility.eligible) {
    return NextResponse.json(
      { error: "Forbidden: Knowledge Exchange is exclusive to ICS." },
      { status: 403 }
    );
  }

  try {
    const [
      totalPosts,
      totalQuestions,
      totalDiscussions,
      answeredQuestions,
      totalAnswers,
      verifiedAnswers,
      totalComments,
      totalTags,
      topTags,
      recentPosts,
    ] = await Promise.all([
      db.kxPost.count({ where: { isDeleted: false } }),
      db.kxPost.count({ where: { postType: "QUESTION", isDeleted: false } }),
      db.kxPost.count({ where: { postType: "DISCUSSION", isDeleted: false } }),
      db.kxPost.count({ where: { status: "ANSWERED", isDeleted: false } }),
      db.kxAnswer.count({ where: { isDeleted: false } }),
      db.kxAnswer.count({ where: { isVerified: true, isDeleted: false } }),
      db.kxComment.count(),
      db.kxTag.count(),
      db.kxTag.findMany({
        orderBy: { postCount: "desc" },
        take: 8,
      }),
      db.kxPost.findMany({
        where: { isDeleted: false },
        orderBy: { createdAt: "desc" },
        take: 5,
        select: {
          id: true,
          title: true,
          postType: true,
          status: true,
          voteCount: true,
          answerCount: true,
          createdAt: true,
        },
      }),
    ]);

    const resolutionRate = totalQuestions > 0 ? Math.round((answeredQuestions / totalQuestions) * 100) : 0;

    return NextResponse.json({
      totalPosts,
      totalQuestions,
      totalDiscussions,
      answeredQuestions,
      totalAnswers,
      verifiedAnswers,
      totalComments,
      totalTags,
      resolutionRate,
      topTags,
      recentPosts,
    });
  } catch (error) {
    console.error("Error loading KX analytics:", error);
    return NextResponse.json({ error: "Internal server error" }, { status: 500 });
  }
}

import { NextResponse } from "next/server";
import { db } from "@/lib/db";
import { checkKxEligibility } from "@/lib/kx-eligibility";
import { awardExpForAcceptedAnswer } from "@/lib/gamification/kx-exp";

export const dynamic = "force-dynamic";

export async function POST(
  request: Request,
  { params }: { params: Promise<{ answerId: string }> }
) {
  const eligibility = await checkKxEligibility(request);
  if (!eligibility) {
    return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
  }
  if (!eligibility.eligible) {
    return NextResponse.json(
      { error: "Forbidden: Knowledge Exchange is exclusive to ICS." },
      { status: 403 }
    );
  }

  const { answerId } = await params;
  const answer = await db.kxAnswer.findUnique({
    where: { id: answerId },
    include: {
      post: {
        select: { id: true, authorId: true, title: true },
      },
    },
  });

  if (!answer || answer.isDeleted) {
    return NextResponse.json({ error: "Answer not found." }, { status: 404 });
  }

  // Accept button visible only to question author
  if (answer.post.authorId !== eligibility.session.user.id) {
    return NextResponse.json(
      { error: "Only the question author can accept an answer." },
      { status: 403 }
    );
  }

  const body = await request.json().catch(() => ({}));
  const isAccepted = body.isAccepted !== undefined ? Boolean(body.isAccepted) : !answer.isAccepted;

  await db.$transaction(async (tx) => {
    if (isAccepted) {
      // Unaccept any previous answers for this post
      await tx.kxAnswer.updateMany({
        where: { postId: answer.postId, isAccepted: true },
        data: { isAccepted: false },
      });

      // Accept this answer
      await tx.kxAnswer.update({
        where: { id: answerId },
        data: { isAccepted: true },
      });

      // Update post status to ANSWERED
      await tx.kxPost.update({
        where: { id: answer.postId },
        data: { status: "ANSWERED" },
      });

      // Notify answer author if not self
      if (answer.authorId !== eligibility.session.user.id) {
        await tx.kxNotification.create({
          data: {
            userId: answer.authorId,
            type: "ACCEPTED",
            title: "Answer Accepted!",
            message: `Your answer to "${answer.post.title}" was accepted as the solution! (+15 EXP)`,
            link: `/ics/knowledge-exchange/post/${answer.postId}#answer-${answerId}`,
          },
        });
      }
    } else {
      // Unaccept
      await tx.kxAnswer.update({
        where: { id: answerId },
        data: { isAccepted: false },
      });

      // Check if any other accepted answers exist
      const remainingAccepted = await tx.kxAnswer.count({
        where: { postId: answer.postId, isAccepted: true },
      });

      if (remainingAccepted === 0) {
        await tx.kxPost.update({
          where: { id: answer.postId },
          data: { status: "OPEN" },
        });
      }
    }
  });

  if (isAccepted) {
    await awardExpForAcceptedAnswer(answer.authorId, answerId).catch(() => {});
  }

  return NextResponse.json({
    success: true,
    answer: { id: answerId, isAccepted },
  });
}

import { NextResponse } from "next/server";
import { db } from "@/lib/db";
import { checkKxEligibility } from "@/lib/kx-eligibility";

export const dynamic = "force-dynamic";

export async function DELETE(
  request: Request,
  { params }: { params: Promise<{ answerId: string }> }
) {
  const eligibility = await checkKxEligibility(request);
  if (!eligibility) {
    return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
  }
  if (!eligibility.eligible) {
    return NextResponse.json(
      { error: "Forbidden: Knowledge Exchange is exclusive to ICS." },
      { status: 403 }
    );
  }

  const { answerId } = await params;
  const answer = await db.kxAnswer.findUnique({
    where: { id: answerId },
    select: { id: true, postId: true, authorId: true, isDeleted: true },
  });

  if (!answer || answer.isDeleted) {
    return NextResponse.json({ error: "Answer not found." }, { status: 404 });
  }

  const isAuthor = answer.authorId === eligibility.session.user.id;
  const isStaff =
    eligibility.role === "ADMIN" || eligibility.role === "INSTRUCTOR";

  if (!isAuthor && !isStaff) {
    return NextResponse.json(
      { error: "You do not have permission to delete this answer." },
      { status: 403 }
    );
  }

  await db.$transaction(async (tx) => {
    await tx.kxAnswer.update({
      where: { id: answerId },
      data: { isDeleted: true },
    });

    await tx.kxPost.update({
      where: { id: answer.postId },
      data: { answerCount: { decrement: 1 } },
    });
  });

  return NextResponse.json({ success: true, message: "Answer deleted." });
}

