    await db.materialAnnotation.delete({
      where: { id },
    });

    return NextResponse.json({ success: true });
  } catch (error) {
    console.error("Error deleting annotation:", error);
    return NextResponse.json(
      { message: "Failed to delete annotation." },
      { status: 500 }
    );
  }
}

