import { PrismaPg } from "@prisma/adapter-pg";
import { PrismaClient } from "@prisma/client";
import { Pool, type PoolConfig } from "pg";

const globalForPrisma = globalThis as unknown as {
  prisma?: PrismaClient;
  pgPool?: Pool;
};

const createPrismaClient = () => {
  // Support standard DATABASE_URL as well as Vercel Postgres / Neon integration variables
  const connectionString =
    process.env.DATABASE_URL ||
    process.env.POSTGRES_PRISMA_URL ||
    process.env.POSTGRES_URL;

  if (!connectionString) {
    throw new Error(
      "[Database Error] No database connection string found. Please set DATABASE_URL (or POSTGRES_PRISMA_URL / POSTGRES_URL) in your environment variables (e.g. in Vercel Project Settings > Environment Variables)."
    );
  }

  if (!globalForPrisma.pgPool) {
    const isProduction = process.env.NODE_ENV === "production";
    const isLocalhost =
      connectionString.includes("localhost") ||
      connectionString.includes("127.0.0.1") ||
      connectionString.includes("::1");

    const poolConfig: PoolConfig = {
      connectionString,
      // In serverless production (e.g. Vercel), limit connections per lambda to prevent pool exhaustion
      max: isProduction ? 2 : 10,
      idleTimeoutMillis: 30000,
      connectionTimeoutMillis: 15000,
      keepAlive: true,
      // Cloud databases (Supabase, Neon, AWS RDS, Railway, Render) require SSL.
      // rejectUnauthorized: false prevents "self-signed certificate in certificate chain" errors
      ssl: !isLocalhost ? { rejectUnauthorized: false } : undefined,
    };

    globalForPrisma.pgPool = new Pool(poolConfig);

    // Handle unexpected idle connection resets gracefully (common with serverless poolers)
    globalForPrisma.pgPool.on("error", (err) => {
      console.warn("PG Pool idle connection notice:", err.message);
    });
  }

  const adapter = new PrismaPg(globalForPrisma.pgPool);
  return new PrismaClient({
    adapter,
    log: process.env.NODE_ENV === "development" ? ["error", "warn"] : ["error"],
  });
};

export const db = globalForPrisma.prisma ?? createPrismaClient();

// Always cache client on globalThis in all environments so warm serverless lambdas reuse the instance
globalForPrisma.prisma = db;

apps/web/src/lib/kx-eligibility.ts.content:
/**
 * apps/web/src/lib/kx-eligibility.ts
 *
 * Single source of truth for determining whether a user can access
 * the Knowledge Exchange (KX) Q&A module.
 *
 * RULE: Strictly gated to users belonging to the Institute of Computer Studies (ICS).
 * Non-ICS institutes (e.g. IBE, ITE) are barred from access.
 */

import { db } from "./db";
import { getSession } from "./auth-session";
import { getSessionFromRequest } from "./api-auth";
import { normalizeRole } from "./admin-types";

/** The institute code that gates access to Knowledge Exchange. */
export const ELIGIBLE_KX_INSTITUTE_CODE = "ics";

/**
 * Minimal session shape needed for eligibility checks.
 */
export interface KxEligibilitySession {
  user: {
    id?: string;
    role?: string;
    instituteId?: string;
  };
}

/**
 * Synchronous check for whether an institute code is eligible for KX.
 *
 * @param instituteCode Institute code string (e.g., "ics", "ibe", "ite")
 * @returns true if code is "ics", false otherwise
 */
export function isEligibleKxInstituteCode(instituteCode?: string | null): boolean {
  if (!instituteCode || typeof instituteCode !== "string") return false;
  return instituteCode.toLowerCase() === ELIGIBLE_KX_INSTITUTE_CODE;
}

/**
 * Checks if a user session or institute code is eligible for Knowledge Exchange.
 * Overloaded to accept an institute code string or a session object.
 *
 * @param target Institute code string or user session
 * @returns boolean or Promise<boolean>
 */
export function isEligibleForKnowledgeExchange(instituteCode: string): boolean;
export function isEligibleForKnowledgeExchange(session: KxEligibilitySession): Promise<boolean>;
export function isEligibleForKnowledgeExchange(
  target: string | KxEligibilitySession | null | undefined
): boolean | Promise<boolean> {
  if (!target) return false;

  if (typeof target === "string") {
    return isEligibleKxInstituteCode(target);
  }

  return (async () => {
    if (!target.user?.instituteId) return false;

    try {
      const institute = await db.institute.findUnique({
        where: { id: target.user.instituteId },
        select: { code: true },
      });

      if (!institute?.code) return false;
      return isEligibleKxInstituteCode(institute.code);
    } catch {
      return false;
    }
  })();
}

/**
 * Full eligibility check for API route handlers and server actions.
 * Resolves session, checks institute, and returns structured result.
 *
 * @param request Optional request for mobile Bearer token resolution
 * @returns Eligibility result and session, or null if unauthenticated
 */
export async function checkKxEligibility(request?: Request) {
  let session = request ? await getSessionFromRequest(request) : await getSession();
  if (!session && !request) {
    // Fallback try request if not passed
    session = await getSession();
  }

  if (!session) {
    return null;
  }

  const role = normalizeRole(session.user.role as string);

  if (request) {
    const headerCode = request.headers.get("x-institute-code");
    if (headerCode && !isEligibleKxInstituteCode(headerCode)) {
      return {
        eligible: false,
        session,
        role,
        instituteCode: headerCode.toLowerCase(),
      };
    }

    try {
      const url = new URL(request.url);
      const queryInstitute = url.searchParams.get("institute");
      if (queryInstitute && !isEligibleKxInstituteCode(queryInstitute)) {
        return {
          eligible: false,
          session,
          role,
          instituteCode: queryInstitute.toLowerCase(),
        };
      }
    } catch {
      // Ignore URL parsing errors
    }
  }

  let instituteCode = "";
  if (session.user.instituteId) {
    const institute = await db.institute.findUnique({
      where: { id: session.user.instituteId },
      select: { code: true },
    });
    if (institute?.code) {
      instituteCode = institute.code.toLowerCase();
    }
  }

  const eligible = isEligibleKxInstituteCode(instituteCode);

  return {
    eligible,
    session,
    role,
    instituteCode,
  };
}

apps/web/src/lib/rbac.ts.content:
/**
 * Role-Based Access Control (RBAC) Module
 *
 * Provides permission checking, role normalization, session guards,
 * and re-authentication utilities for the admin system.
 */

import { db } from './db';
import { getSession } from './auth-session';
import { compare } from 'bcryptjs';
import {
  normalizeRole,
  DEFAULT_ROLE_PERMISSIONS,
  type UserRole,
  type SystemPermission,
} from './admin-types';

// Re-export for convenience
export { normalizeRole } from './admin-types';

// ─── Permission Helpers ───

/**
 * Parses the JSON permissions string stored in the database.
 * Returns an empty array on parse failure.
 */
export function parsePermissions(raw: string): string[] {
  try {
    const parsed = JSON.parse(raw);
    return Array.isArray(parsed) ? parsed : [];
  } catch {
    return [];
  }
}

/**
 * Checks if a user's permission array includes the required permission.
 */
export function hasPermission(
  permissions: string[],
  required: SystemPermission
): boolean {
  return permissions.includes(required);
}

/**
 * Returns the default permission set for a given role.
 */
export function getDefaultPermissions(role: UserRole): SystemPermission[] {
  return DEFAULT_ROLE_PERMISSIONS[role] ?? [];
}

// ─── Session Guards ───

export interface AdminSession {
  sessionId: string;
  user: {
    id: string;
    name: string;
    email: string;
    role: string;
    isActive: boolean;
    permissions: string;
    instituteId: string;
  };
}

/**
 * Validates the current session and returns it.
 * Returns null if no valid session exists.
 */
export async function getValidSession(): Promise<AdminSession | null> {
  const session = await getSession();
  if (!session) return null;

  return {
    sessionId: session.id,
    user: {
      id: session.user.id,
      name: session.user.name,
      email: session.user.email,
      role: session.user.role,
      isActive: (session.user as Record<string, unknown>).isActive !== false,
      permissions: ((session.user as Record<string, unknown>).permissions as string) ?? '[]',
      instituteId: session.user.instituteId,
    },
  };
}

/**
 * Requires the current user to be an authenticated ADMIN.
 * Returns the session or throws a Response-compatible error object.
 */
export async function requireAdmin(): Promise<AdminSession> {
  const session = await getValidSession();

  if (!session) {
    throw { status: 401, message: 'Authentication required.' };
  }

  const role = normalizeRole(session.user.role);
  if (role !== 'ADMIN') {
    throw { status: 403, message: 'Forbidden: Admin access required.' };
  }

  if (!session.user.isActive) {
    throw { status: 403, message: 'Your account has been deactivated. Please contact administration.' };
  }

  return session;
}

/**
 * Requires the current user to have a specific permission.
 */
export async function requirePermission(
  permission: SystemPermission
): Promise<AdminSession> {
  const session = await getValidSession();

  if (!session) {
    throw { status: 401, message: 'Authentication required.' };
  }

  if (!session.user.isActive) {
    throw { status: 403, message: 'Your account has been deactivated. Please contact administration.' };
  }

  const role = normalizeRole(session.user.role);
  if (role === 'ADMIN') return session; // Admins always pass

  const userPermissions = parsePermissions(session.user.permissions);
  if (!hasPermission(userPermissions, permission)) {
    throw { status: 403, message: `Forbidden: Missing permission '${permission}'.` };
  }

  return session;
}

/**
 * Re-authentication check for sensitive operations (e.g., role changes).
 * Requires the admin to provide their current password.
 */
export async function requireReAuth(
  adminId: string,
  password: string
): Promise<boolean> {
  const admin = await db.user.findUnique({
    where: { id: adminId },
    select: { password: true },
  });

  if (!admin) {
    throw { status: 404, message: 'Admin user not found.' };
  }

  const valid = await compare(password, admin.password);
  if (!valid) {
    throw { status: 401, message: 'Re-authentication failed. Incorrect password.' };
  }

  return true;
}

// ─── Audit Logging ───

/**
 * Creates an immutable audit log entry.
 */
export async function createAuditLog(params: {
  adminId: string;
  targetId: string;
  action: string;
  ipAddress?: string;
  metadata?: Record<string, unknown>;
}): Promise<void> {
  await db.auditLog.create({
    data: {
      adminId: params.adminId,
      targetId: params.targetId,
      action: params.action,
      ipAddress: params.ipAddress ?? '',
      metadata: params.metadata ? JSON.stringify(params.metadata) : '{}',
    },
  });
}

/**
 * Extracts the client IP address from request headers.
 */
export function getClientIp(request: Request): string {
  const forwarded = request.headers.get('x-forwarded-for');
  if (forwarded) {
    return forwarded.split(',')[0].trim();
  }
  const realIp = request.headers.get('x-real-ip');
  return realIp ?? '127.0.0.1';
}

