import * as fs from 'node:fs';
import * as path from 'node:path';
import { createHash } from 'node:crypto';
import { Client } from 'pg';

export type Institute = 'ics' | 'ibe' | 'ite';
export type Role = 'SUPER_USER' | 'ADMIN' | 'INSTRUCTOR' | 'STUDENT' | 'OTHER_STUDENT' | 'INACTIVE_USER' | 'FOREIGN_INSTRUCTOR' | 'UNASSIGNED_INSTRUCTOR' | 'ADMIN_TARGET';
export interface CourseFixture {
  id: string; title: string; instituteId: string; instructorId: string;
  scheduleId: string; announcementId: string; materialId: string; assignmentId: string;
  studentSubmissionId: string; superSubmissionId: string; templateId: string; pendingEnrollmentId: string;
}
export interface Fixture {
  version: 2; fixtureId: string; baseURL: string; databaseHash: string; schemaHash: string;
  accounts: Record<Role, { id: string; token: string; email: string; loginPassword: string; rawRole: string; institute: Institute; active: boolean }>;
  courses: Record<Institute, CourseFixture>; superAssignedCourse: CourseFixture;
  studentMarkers: string[]; restrictedRecordMarkers: string[];
}
export const institutes: Institute[] = ['ics', 'ibe', 'ite'];
export const prohibitedRoles: Role[] = ['ADMIN', 'INSTRUCTOR', 'STUDENT', 'OTHER_STUDENT', 'INACTIVE_USER', 'FOREIGN_INSTRUCTOR', 'UNASSIGNED_INSTRUCTOR'];
export const securityBoundaries = ['authentication', 'authorization', 'ownership', 'institute-scope', 'program-scope', 'idor', 'privilege-escalation', 'direct-api', 'request-manipulation', 'sensitive-data'];
export const sha = (value: string | Buffer) => createHash('sha256').update(value).digest('hex');

export function databaseURL(): string {
  const value = process.env.HARNESS_TEST_DATABASE_URL;
  if (!value) throw new Error('Explicit disposable database configuration is required');
  const url = new URL(value);
  if (!['postgres:', 'postgresql:'].includes(url.protocol) || !['127.0.0.1', 'localhost', '[::1]'].includes(url.hostname) || !/^\/harness_[a-zA-Z0-9_]+$/.test(url.pathname) || url.search) throw new Error('Refuse a live/proxied database');
  return value;
}
export function loadFixture(): Fixture {
  let file = process.env.HARNESS_LMS_FIXTURE_PATH;
  if (!file) {
    const run = process.env.HARNESS_RUN_ID;
    if (!run || !/^run_[a-zA-Z0-9_-]+$/.test(run)) throw new Error('Host fixture path or run locator is required');
    const locator = JSON.parse(fs.readFileSync(path.resolve('.orchestra/runs', run, 'lms-fixture-locator.json'), 'utf8'));
    if (locator.version !== 1 || locator.runId !== run) throw new Error('Foreign fixture locator');
    file = locator.file;
    if (!path.isAbsolute(file!)) throw new Error('Fixture locator must be absolute');
    if (sha(fs.readFileSync(file!)) !== locator.sha256) throw new Error('Host fixture configuration changed');
  }
  const f = JSON.parse(fs.readFileSync(file!, 'utf8')) as Fixture;
  const base = new URL(f.baseURL), expected = process.env.HARNESS_TEST_BASE_URL || process.env.E2E_BASE_URL;
  if (f.version !== 2 || base.protocol !== 'http:' || !['127.0.0.1', 'localhost', '[::1]'].includes(base.hostname) || (expected && new URL(expected).origin !== base.origin)) throw new Error('Foreign/non-loopback test server');
  if (f.databaseHash !== sha(databaseURL())) throw new Error('Fixture database target differs');
  if (f.studentMarkers.length < 6 || f.restrictedRecordMarkers.length < 4) throw new Error('Complete seeded privacy markers are required');
  for (const role of ['SUPER_USER', ...prohibitedRoles, 'ADMIN_TARGET'] as Role[]) if (!f.accounts[role]?.id || !f.accounts[role].token) throw new Error('Missing test identity: ' + role);
  if (f.accounts.SUPER_USER.rawRole !== 'SUPER_USER' || f.accounts.SUPER_USER.institute !== 'ics' || !f.accounts.SUPER_USER.active || f.accounts.INACTIVE_USER.active || f.accounts.INSTRUCTOR.rawRole !== 'PROFESSOR' || f.accounts.STUDENT.rawRole !== 'STUDENT') throw new Error('Fixture role/alias contract differs');
  return f;
}
export const auth = (f: Fixture, role: Role) => ({ Authorization: `Bearer ${f.accounts[role].token}`, Cookie: `lumina_session=${f.accounts[role].token}` });
export const overview = (f: Fixture, institute: string) => `${f.baseURL}/api/academic-oversight/${encodeURIComponent(institute)}/courses`;
export const detail = (f: Fixture, institute: string, course: string) => `${overview(f, institute)}/${encodeURIComponent(course)}`;
export async function database<T>(action: (client: Client) => Promise<T>): Promise<T> {
  const client = new Client({ connectionString: databaseURL() }); await client.connect();
  try { return await action(client); } finally { await client.end(); }
}
export async function assertSeeded(f: Fixture): Promise<void> {
  await database(async client => {
    for (const role of Object.keys(f.accounts) as Role[]) {
      const a = f.accounts[role], result = await client.query('SELECT u.role,u."isActive",i.code FROM "User" u JOIN "Institute" i ON i.id=u."instituteId" WHERE u.id=$1', [a.id]);
      if (result.rows.length !== 1 || result.rows[0].role !== a.rawRole || result.rows[0].isActive !== a.active || result.rows[0].code !== a.institute) throw new Error('Test identity not actually seeded: ' + role);
    }
    for (const c of [...Object.values(f.courses), f.superAssignedCourse]) {
      const actual = (await client.query('SELECT "instituteId","instructorId" FROM "Course" WHERE id=$1', [c.id])).rows[0];
      if (!actual || actual.instituteId !== c.instituteId || actual.instructorId !== c.instructorId) throw new Error('Course ownership fixture differs');
    }
    const enrolled = (await client.query('SELECT status FROM "Enrollment" WHERE "courseId"=$1 AND "studentId"=$2', [f.courses.ics.id, f.accounts.STUDENT.id])).rows[0];
    if (enrolled?.status !== 'APPROVED') throw new Error('Positive student is not enrolled');
    const forged = (await client.query('SELECT status FROM "Enrollment" WHERE "courseId"=$1 AND "studentId"=$2', [f.superAssignedCourse.id, f.accounts.SUPER_USER.id])).rows[0];
    if (forged?.status !== 'APPROVED') throw new Error('Adversarial SUPER_USER ownership/enrollment fixture missing');
  });
}
// Snapshot every public base table, including identities, sessions, all teaching,
// assessment, attempt, attachment, notification and grade/gamification state.
// AuditLog is excluded because legitimate access/denial evidence is append-only.
export async function stateFingerprint(): Promise<string> {
  return database(async client => {
    const names = (await client.query("SELECT table_name FROM information_schema.tables WHERE table_schema='public' AND table_type='BASE TABLE' AND table_name NOT IN ('AuditLog','_prisma_migrations') ORDER BY table_name")).rows;
    const state: Record<string, unknown> = {};
    for (const { table_name: name } of names) {
      const identifier = '"' + String(name).replaceAll('"', '""') + '"';
      state[name] = (await client.query(`SELECT to_jsonb(t) AS record FROM ${identifier} t ORDER BY to_jsonb(t)::text`)).rows;
    }
    return sha(JSON.stringify(state));
  });
}
export async function auditBaseline(): Promise<Record<string, string>> {
  return database(async client => Object.fromEntries((await client.query('SELECT id,to_jsonb(a) AS record FROM "AuditLog" a ORDER BY id')).rows.map(r => [r.id, sha(JSON.stringify(r.record))])));
}
export async function assertAuditAppendOnly(before: Record<string, string>): Promise<void> {
  const after = await auditBaseline(); for (const [id, value] of Object.entries(before)) if (after[id] !== value) throw new Error('An existing audit record changed or disappeared');
}
export function noSensitive(f: Fixture, value: unknown): void {
  const text = typeof value === 'string' ? value : JSON.stringify(value);
  for (const marker of [...f.studentMarkers, ...f.restrictedRecordMarkers]) if (text.includes(marker)) throw new Error('Restricted fixture marker leaked');
}
function exact(value: unknown, required: string[], optional: string[] = []): Record<string, unknown> {
  if (!value || typeof value !== 'object' || Array.isArray(value)) throw new Error('Expected response object');
  const o = value as Record<string, unknown>, keys = Object.keys(o);
  if (required.some(k => !keys.includes(k)) || keys.some(k => ![...required, ...optional].includes(k))) throw new Error('Response exceeds explicit allowlist');
  return o;
}
function strings(o: Record<string, unknown>, keys: string[]): void { for (const k of keys) if (typeof o[k] !== 'string') throw new Error('Invalid scalar: ' + k); }
function instituteShape(value: unknown): Record<string, unknown> { const o = exact(value, ['id', 'code', 'name']); strings(o, ['id', 'code', 'name']); return o; }
function courseShape(value: unknown, full: boolean): Record<string, unknown> {
  const o = exact(value, ['id', 'code', 'courseCode', 'title', 'section', 'subject', 'room', 'description', 'coverImage', 'instructor', ...(full ? ['schedule', 'announcements', 'materials'] : [])]);
  strings(o, ['id', 'code', 'courseCode', 'title', 'section', 'subject', 'room', 'description', 'coverImage']);
  if (o.instructor !== null) { const i = exact(o.instructor, ['id', 'name']); strings(i, ['id', 'name']); }
  if (full) {
    for (const k of ['schedule', 'announcements', 'materials']) if (!Array.isArray(o[k])) throw new Error('Expected summary array: ' + k);
    for (const v of o.schedule as unknown[]) { const s = exact(v, ['id', 'title', 'eventDate', 'eventType', 'description']); strings(s, ['id', 'title', 'eventDate', 'eventType', 'description']); if (!Number.isFinite(Date.parse(String(s.eventDate)))) throw new Error('Invalid schedule date'); }
    for (const v of o.announcements as unknown[]) { const a = exact(v, ['id', 'content', 'createdAt']); strings(a, ['id', 'content', 'createdAt']); }
    for (const v of o.materials as unknown[]) { const m = exact(v, ['id', 'title', 'type', 'description', 'dueDate']); strings(m, ['id', 'title', 'type', 'description']); if (m.dueDate !== null && typeof m.dueDate !== 'string') throw new Error('Invalid material date'); }
  }
  return o;
}
export function overviewShape(f: Fixture, value: unknown, selected: Institute): Record<string, unknown> {
  noSensitive(f, value); const o = exact(value, ['institute', 'courses']);
  if (instituteShape(o.institute).code !== selected || !Array.isArray(o.courses)) throw new Error('Selected institute/list differs');
  const expected = selected === 'ics' ? [f.courses.ics, f.superAssignedCourse] : [f.courses[selected]];
  const ids = o.courses.map(c => String(courseShape(c, false).id));
  if (new Set(ids).size !== ids.length || JSON.stringify([...ids].sort()) !== JSON.stringify(expected.map(c => c.id).sort())) throw new Error('Overview course set is not exactly the selected institute fixture');
  for (const value of o.courses) {
    const c = courseShape(value, false), seeded = expected.find(e => e.id === c.id)!;
    if (c.title !== seeded.title || !c.instructor || (c.instructor as Record<string, unknown>).id !== seeded.instructorId) throw new Error('Overview course/assigned instructor differs');
  }
  return o;
}
export function detailShape(f: Fixture, value: unknown, selected: Institute, expected: CourseFixture): Record<string, unknown> {
  noSensitive(f, value); const o = exact(value, ['institute', 'course']);
  if (instituteShape(o.institute).code !== selected) throw new Error('Selected detail institute differs');
  const c = courseShape(o.course, true); if (c.id !== expected.id || c.title !== expected.title || !c.instructor || (c.instructor as Record<string, unknown>).id !== expected.instructorId) throw new Error('Course/instructor scope differs');
  return c;
}
export function errorShape(f: Fixture, value: unknown): void {
  noSensitive(f, value); const o = exact(value, [], ['error', 'message', 'code']);
  if (!Object.keys(o).length || Object.values(o).some(v => typeof v !== 'string')) throw new Error('Unsafe error response');
}
export interface Evidence { actor: Role; institute: string; target: string; operation: string; outcome: 'DENIED' | 'ALLOWED'; status: number | string; before?: string; after?: string }
export function controllerEvidence(evidence: Evidence): void {
  const run = process.env.HARNESS_RUN_ID || 'fixture-diagnostic';
  if (!/^[a-zA-Z0-9_-]+$/.test(run)) throw new Error('Unsafe evidence run ID');
  const directory = path.resolve('.orchestra/runs', run, 'authorization-fixture-evidence'); fs.mkdirSync(directory, { recursive: true });
  fs.appendFileSync(path.join(directory, 'requests.jsonl'), JSON.stringify({ ...evidence, runId: run, environment: process.env.HARNESS_ENVIRONMENT_ID || 'diagnostic', at: new Date().toISOString() }) + '\n');
}
export async function auditRead(f: Fixture, action: string, selected: Institute, courseId: string | null, since: Date): Promise<void> {
  const rows = await database(async c => (await c.query('SELECT "adminId","targetId",action,metadata,"createdAt" FROM "AuditLog" WHERE "adminId"=$1 AND action=$2 AND "createdAt">=$3', [f.accounts.SUPER_USER.id, action, since])).rows);
  if (!rows.some(r => { const m = typeof r.metadata === 'string' ? JSON.parse(r.metadata) : r.metadata; return r.targetId === f.accounts.SUPER_USER.id && m.outcome === 'ALLOWED' && m.institute === selected && (courseId === null || m.courseId === courseId); })) throw new Error('Selected-institute actor/target/outcome access audit missing');
}
export function activityPayload(f: Fixture, actor: Role, institute: Institute) { return { studentId: f.accounts[actor].id, assignmentId: f.courses[institute].templateId, activityType: 'pc-build', variantSeed: 'fixture-seed', startedAt: new Date().toISOString(), completionTimeSeconds: 1, attempts: 1, stateCheck: { fixture: true }, score: 0, maxScore: 100, passed: false, errorLog: [] }; }
export function httpMutations(f: Fixture, institute: Institute) {
  const c = f.courses[institute];
  return [
    { category: 'schedule-edit', path: '/api/workspace/events', method: 'POST', body: { title: 'Denied schedule', eventDate: new Date(Date.now() + 86400000).toISOString(), eventType: 'class', courseId: c.id } },
    { category: 'schedule-edit', path: '/api/workspace/events', method: 'PATCH', body: { id: c.scheduleId, title: 'Denied edit', eventDate: new Date(Date.now() + 86400000).toISOString(), courseId: c.id } },
    { category: 'schedule-edit', path: '/api/workspace/events?id=' + c.scheduleId, method: 'DELETE' },
    { category: 'grade-work', path: `/api/courses/${c.id}/submissions/grade`, method: 'POST', body: { submissionId: c.studentSubmissionId, grade: 17, feedback: 'Denied feedback' } },
    { category: 'enrollment-edit', path: `/api/courses/${c.id}/enrollments`, method: 'PATCH', body: { enrollmentId: c.pendingEnrollmentId, action: 'APPROVE' } },
    { category: 'assessment-submit', path: '/api/activities/submit', method: 'POST', body: activityPayload(f, 'SUPER_USER', institute) },
    { category: 'admin-only', path: `/api/admin/users/${f.accounts.ADMIN_TARGET.id}/status`, method: 'PATCH', body: { isActive: false } },
    { category: 'admin-only', path: `/api/admin/users/${f.accounts.ADMIN_TARGET.id}/role`, method: 'PATCH', body: { newRole: 'ADMIN', adminPassword: f.accounts.SUPER_USER.loginPassword } },
  ] as const;
}
